package com.campus.lostfound.security;
import com.campus.lostfound.repository.UserRepository; import com.campus.lostfound.domain.User; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.csrf.CookieCsrfTokenRepository; import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService userDetailsService(UserRepository users){return email->users.findByEmail(email.toLowerCase()).map(u->org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPasswordHash()).roles(u.getRole().name()).build()).orElseThrow(()->new UsernameNotFoundException("Account not found"));}
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.csrf(c->c.csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse()).csrfTokenRequestHandler(new CsrfTokenRequestAttributeHandler()).ignoringRequestMatchers("/api/auth/register")).authorizeHttpRequests(a->a.requestMatchers("/","/index.html","/css/**","/js/**","/api/auth/register","/api/auth/login","/api/csrf","/api/public/**","/media/**","/error").permitAll().requestMatchers("/api/admin/**").hasAnyRole("ADMIN","STAFF").anyRequest().authenticated()).formLogin(f->f.disable()).httpBasic(b->b.disable()).logout(l->l.logoutUrl("/api/auth/logout").logoutSuccessHandler((req,res,auth)->res.setStatus(204))).build();}
}
